// استمارة تسجيل المخازن - مع نظام الهوية (Auth) - Minified Version
document.addEventListener('DOMContentLoaded',function(){console.log('📝 تهيئة استمارة تسجيل المخازن (مع نظام الهوية)');const form=document.getElementById('warehouseForm');if(!form){console.error('❌ لم يتم العثور على استمارة التسجيل');return}const supabaseUrl='https://slamtak.supabase.co';const supabaseKey='eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InNsYW10YWsiLCJyb2xlIjoiYW5vbiIsImlhdCI6MTY5ODc2NjQzNCwiZXhwIjoyMDE0MzQyNDM0fQ.3Q4Y7F2aX9wZ8bL5pK6nH7gJ8tR9sX1yV2wZ3bL4mN5oP6qR7sT8uV9wX0yZ1a';const supabase=window.supabase.createClient(supabaseUrl,supabaseKey);form.addEventListener('submit',async function(e){console.log('🔄 بدء معالجة استمارة التسجيل');const formData={name:document.getElementById('storeName').value.trim(),phone:document.getElementById('phone').value.trim(),region:document.getElementById('governorate').value.trim(),email:document.getElementById('email').value.trim(),password:document.getElementById('password').value,confirm_password:document.getElementById('confirmPassword').value};console.log('📋 البيانات المدخلة:',formData);if(!formData.name||!formData.phone||!formData.email||!formData.password){alert('يرجى ملء جميع الحقول المطلوبة');return}if(formData.phone.length!==11){alert('التليفون يجب أن يكون 11 رقم');return}if(formData.password!==formData.confirm_password){alert('كلمتا المرور غير متطابقتين');return}try{console.log('🔐 جاري إنشاء حساب المستخدم...');const{data:authData,error:authError}=await supabase.auth.signUp({email:formData.email,password:formData.password,options:{data:{name:formData.name,phone:formData.phone,region:formData.region}}});if(authError){console.error('❌ خطأ في إنشاء حساب المستخدم:',authError);alert('فشل إنشاء الحساب: '+authError.message);return}console.log('✅ تم إنشاء حساب المستخدم بنجاح:',authData);console.log('💾 جاري حفظ بيانات المخزن...');const{data:warehouseData,error:warehouseError}=await supabase.from('warehouses').insert([{id:authData.user.id,name:formData.name,phone:formData.phone,region:formData.region,email:formData.email}]);if(warehouseError){console.error('❌ خطأ في حفظ بيانات المخزن:',warehouseError);alert('فشل حفظ بيانات المخزن: '+warehouseError.message);return}console.log('✅ تم حفظ بيانات المخزن بنجاح:',warehouseData);localStorage.setItem('warehouseData',JSON.stringify({...formData,user_id:authData.user.id}));console.log('✅ تم حفظ نسخة احتياطية في localStorage');alert('تم التسجيل بنجاح! تم إنشاء حسابك الشخصي.');console.log('Attempting to redirect...');window.location.href='https://slamtak.pages.dev/dashboard.html'}catch(error){console.error('❌ خطأ غير متوقع:',error);alert('حدث خطأ أثناء التسجيل')}});console.log('✅ تم تهيئة استمارة التسجيل بنجاح')});
